// Frozen run-65 payout schedule; new deployments use the wild-color schedule.
const DEGENERETTE_CURRENCY = { ETH: 0, FLIP: 1, WWXRP: 3 };
const QUICK_PLAY_PAYOUTS_PACKED = 0x0000f424000030d4000009c4000003e80000012c000000320000000000000000n;
const QUICK_PLAY_PAYOUT_S8 = 2_035_457n;
const QUICK_PLAY_PAYOUT_S9 = 25_025_025n;
// ETH's flat +5 percentage points, EV-allocated across scores 6-9 (10/30/30/30
// of the bump to scores 6/7/8/9).
const ETH_BONUS_FACTORS_PACKED = 0x000000000110cb290000000000458ce600000000006cdd2100000000000f7734n;
const BONUS_FACTOR_SCALE = 1_000_000n;
// WWXRP keeps its own 8/9 prizes and sits outside the paid-bet ceiling. It
// normalizes its rigged/gold base to a fixed pre-scaled floor, then allocates
// activity's extra return (above the WWXRP floor bps) onto 6-9.
const WWXRP_FLOOR_SCALED = 6_165_869_671n;
const WWXRP_PAYOUT_S8 = 480_677n;
const WWXRP_PAYOUT_S9 = 100_000_000n;
const WWXRP_BONUS_FACTORS_PACKED = 0x000000000044444400000000008faa84000000000046626100000000000bb73bn;
const ROI_MIN_BPS = 9_000n;
const ROI_VA_BPS = 9_891n;
const ROI_VB_BPS = 9_970n;
const ROI_MAX_BPS = 9_990n;
const ETH_ROI_BONUS_BPS = 500n;
const WWXRP_ROI_MIN_BPS = 7_000n;
const WWXRP_ROI_VA_BPS = 12_400n;
const WWXRP_ROI_VB_BPS = 12_760n;
const WWXRP_ROI_MAX_BPS = 13_000n;

const PAYOUT_LANE_MASK = 0xFFFFFFFFn;
const FACTOR_LANE_MASK = 0xFFFFFFFFFFFFFFFFn;
const PAYOUT_DIVISOR = 4_000_000_000_000n; // 100 (base centi) x 4 (gold ratio) x 1e10 (bps x scale)
// ActivityCurveLib knees — unchanged by a5d4d2cd.
const ACTIVITY_K = 305n;
const ACTIVITY_KNEE = 500n;
const ACTIVITY_CAP = 30_000n;

function _curve(score, min, valueA, valueB, max) {
  const s = score < 0n ? 0n : score;
  if (s >= ACTIVITY_CAP) return max;
  if (s <= ACTIVITY_K) return min + (s * (valueA - min)) / ACTIVITY_K;
  if (s <= ACTIVITY_KNEE) {
    return valueA + ((s - ACTIVITY_K) * (valueB - valueA)) / (ACTIVITY_KNEE - ACTIVITY_K);
  }
  return valueB + ((s - ACTIVITY_KNEE) * (max - valueB)) / (ACTIVITY_CAP - ACTIVITY_KNEE);
}

function _basePayoutCentiX(score) {
  if (score >= 9) return QUICK_PLAY_PAYOUT_S9;
  if (score === 8) return QUICK_PLAY_PAYOUT_S8;
  return (QUICK_PLAY_PAYOUTS_PACKED >> (BigInt(score) * 32n)) & PAYOUT_LANE_MASK;
}

function _bonusFactor(packed, score) {
  if (score < 6) return 0n;
  return (packed >> (BigInt(score - 6) * 64n)) & FACTOR_LANE_MASK;
}

/**
 * Exact gross-return schedule for one Degenerette currency/activity/gold-match
 * combination. `multiplierHundredths` is rounded only for display;
 * `multiplierNumerator`/`multiplierDenominator` retain the contract's exact
 * `base x (4+goldMatches) x scaledRoi / 4e12` fraction.
 *
 * @param {{currency?: number, activityScore?: number|bigint,
 *           goldMatches?: number}} args `goldMatches` (0-4) is the number of
 *           quadrants where the rolled color matched AND was gold — unknowable
 *           before resolution, so callers previewing a bet should leave it at
 *           the default 0 (the guaranteed floor, no gold boost assumed).
 */
export function degenerettePayoutTable({
  currency = DEGENERETTE_CURRENCY.ETH,
  activityScore = 0,
  goldMatches = 0,
} = {}) {
  const cur = Number(currency);
  if (![DEGENERETTE_CURRENCY.ETH, DEGENERETTE_CURRENCY.FLIP, DEGENERETTE_CURRENCY.WWXRP].includes(cur)) {
    throw new Error('Unsupported Degenerette currency.');
  }
  let activity;
  try { activity = BigInt(activityScore); }
  catch (_e) { activity = 0n; }
  if (activity < 0n) activity = 0n;
  let gold = Number(goldMatches);
  if (!Number.isInteger(gold)) gold = 0;
  if (gold < 0) gold = 0;
  if (gold > 4) gold = 4;

  const isWwxrp = cur === DEGENERETTE_CURRENCY.WWXRP;
  const rows = [];
  for (let score = 0; score <= 9; score += 1) {
    let basePayoutCentiX = _basePayoutCentiX(score);
    if (isWwxrp && score === 8) basePayoutCentiX = WWXRP_PAYOUT_S8;
    else if (isWwxrp && score === 9) basePayoutCentiX = WWXRP_PAYOUT_S9;
    let scaledRoi;
    let bonusBps = 0n;
    let bonusFactors = 0n;
    if (isWwxrp) {
      scaledRoi = WWXRP_FLOOR_SCALED;
      if (score >= 6) {
        bonusBps = _curve(activity, WWXRP_ROI_MIN_BPS, WWXRP_ROI_VA_BPS, WWXRP_ROI_VB_BPS, WWXRP_ROI_MAX_BPS)
          - WWXRP_ROI_MIN_BPS;
        bonusFactors = WWXRP_BONUS_FACTORS_PACKED;
      }
    } else {
      scaledRoi = _curve(activity, ROI_MIN_BPS, ROI_VA_BPS, ROI_VB_BPS, ROI_MAX_BPS) * BONUS_FACTOR_SCALE;
      if (cur === DEGENERETTE_CURRENCY.ETH && score >= 6) {
        bonusBps = ETH_ROI_BONUS_BPS;
        bonusFactors = ETH_BONUS_FACTORS_PACKED;
      }
    }
    if (bonusBps !== 0n) {
      scaledRoi += bonusBps * _bonusFactor(bonusFactors, score);
    }
    const multiplierNumerator = basePayoutCentiX * BigInt(4 + gold) * scaledRoi;
    rows.push(Object.freeze({
      score,
      basePayoutCentiX,
      scaledRoi,
      multiplierNumerator,
      multiplierDenominator: PAYOUT_DIVISOR,
      multiplierHundredths: (multiplierNumerator * 100n + PAYOUT_DIVISOR / 2n) / PAYOUT_DIVISOR,
    }));
  }
  return Object.freeze({
    currency: cur,
    activityScore: activity,
    goldMatches: gold,
    rows: Object.freeze(rows),
  });
}

/** Format `multiplierHundredths` without crossing through lossy Number math. */
export function formatDegeneretteMultiplier(multiplierHundredths) {
  let value;
  try { value = BigInt(multiplierHundredths); } catch (_e) { return '—'; }
  const whole = value / 100n;
  const cents = value % 100n;
  if (value === 0n) return '0×';
  return `${whole.toLocaleString('en-US')}.${cents.toString().padStart(2, '0')}×`;
}

/**
 * One settled spin's payout, exactly as _degenerettePayout computes it:
 * `amountPerSpin × base(S) × (4 + gold) × scaledRoi / 4e12`. This is the gross
 * the spin produced before the ETH 3-tier split / pool cap and before a FLIP
 * bet's survival flip — the value the retired DegeneretteResult.payout carried.
 */
export function degeneretteSpinPayout({
  currency,
  amountPerSpin,
  activityScore = 0,
  score,
  goldMatches = 0,
} = {}) {
  let stake;
  try { stake = BigInt(amountPerSpin ?? 0); } catch (_e) { return 0n; }
  const s = Number(score);
  if (stake <= 0n || !Number.isInteger(s) || s < 0 || s > 9) return 0n;
  const row = degenerettePayoutTable({ currency, activityScore, goldMatches }).rows[s];
  if (!row || row.multiplierNumerator === 0n) return 0n;
  return (stake * row.multiplierNumerator) / row.multiplierDenominator;
}

